import React from 'react';
import { motion } from 'framer-motion';
import { Lock, User, ShieldCheck, ArrowRight } from 'lucide-react';

const Login = () => {
  return React.createElement('div', { className: "min-h-screen w-full flex items-center justify-center relative overflow-hidden bg-blue-linen" },
    // Background Glows
    React.createElement('div', { className: "absolute top-[-10%] left-[-10%] w-[500px] h-[500px] rounded-full bg-sungold/20 blur-[120px] animate-pulse" }),
    React.createElement('div', { className: "absolute bottom-[-10%] right-[-10%] w-[500px] h-[500px] rounded-full bg-seed-green/20 blur-[120px] animate-pulse" }),

    // Login Card
    React.createElement(motion.div, {
      initial: { opacity: 0, y: 30 },
      animate: { opacity: 1, y: 0 },
      transition: { duration: 0.8 },
      className: "relative z-10 w-full max-w-md p-10 mx-4 rounded-[2.5rem] border border-white/40 shadow-2xl backdrop-blur-xl bg-white/30"
    },
      // Logo
      React.createElement('div', { className: "text-center mb-10" },
        React.createElement(motion.div, {
          initial: { scale: 0 },
          animate: { scale: 1 },
          className: "w-20 h-20 bg-sungold rounded-3xl mx-auto mb-6 flex items-center justify-center shadow-lg shadow-sungold/40"
        }, React.createElement(ShieldCheck, { size: 42, className: "text-butter-bean" })),
        React.createElement('h1', { className: "text-4xl font-black text-grassy-green tracking-tight" }, "ADMIN", React.createElement('span', { className: "text-sungold" }, ".")),
        React.createElement('p', { className: "text-grassy-green/70 mt-2 font-medium uppercase text-xs" }, "Eco-System Control Center")
      ),

      // Form
      React.createElement('form', { className: "space-y-5" },
        React.createElement('div', { className: "space-y-1" },
          React.createElement('label', { className: "text-xs font-bold text-grassy-green uppercase ml-2" }, "Administrator ID"),
          React.createElement('div', { className: "relative" },
            React.createElement(User, { className: "absolute left-4 top-1/2 -translate-y-1/2 text-grassy-green/40", size: 20 }),
            React.createElement('input', { className: "w-full pl-12 pr-4 py-4 rounded-2xl bg-white/50 border border-white/20 outline-none text-grassy-green", placeholder: "admin@eco.com" })
          )
        ),
        React.createElement('div', { className: "space-y-1" },
          React.createElement('label', { className: "text-xs font-bold text-grassy-green uppercase ml-2" }, "Security Key"),
          React.createElement('div', { className: "relative" },
            React.createElement(Lock, { className: "absolute left-4 top-1/2 -translate-y-1/2 text-grassy-green/40", size: 20 }),
            React.createElement('input', { type: "password", className: "w-full pl-12 pr-4 py-4 rounded-2xl bg-white/50 border border-white/20 outline-none text-grassy-green", placeholder: "••••••••" })
          )
        ),
        React.createElement(motion.button, {
          whileHover: { scale: 1.02 },
          className: "w-full py-4 mt-4 bg-sungold text-white font-black rounded-2xl shadow-xl flex items-center justify-center gap-3"
        }, "INITIALIZE SESSION", React.createElement(ArrowRight, { size: 20 }))
      )
    )
  );
};

export default Login;
